   [108]={next_id=109, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我想，请您将您的想法都写进一封信里。让蒂雅知道，她做得够好了。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [109]={next_id=110, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="听到你的话，蒂雅的父亲站起身，走到窗边，看着窗外的景色，眼中有着追忆闪过。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [110]={next_id=111, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那孩子……", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [111]={next_id=112, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="从小就懂事到让人心疼。她总是默默的努力着，从来不跟我说苦，从来不喊累。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [112]={next_id=113, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可我知道，她很累，也很无助。对自己要求太高，努力的回应着每个人。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [113]={next_id=114, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="有的时候，我多想告诉她，她已经做得足够好了，该歇一歇了，可……看到她认真的脸庞又不忍心开口……", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [114]={next_id=115, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他走回书桌前，拿起羽毛笔，低头写字。写得很慢，写写停停，像是在心里反复斟酌每一个字。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [115]={next_id=116, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="写完后，他将信纸折好递给你。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [116]={next_id=117, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="链尉官，就拜托你了。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [117]={next_id=118, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="嗯。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [118]={next_id=119, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你郑重的点了点头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [119]={next_id=120, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="还有。我希望，您能将天文馆的守卫撤离，并让我使用天文馆三天。", msg_color="", msg_size=0, talker="玩家名字", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [120]={next_id=121, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="蒂雅的父亲沉默了一会，随后点点头。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [121]={next_id=122, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可以。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [122]={next_id=123, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="虽然这么做会遭到族里那些老家伙们的反对，但……", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [123]={next_id=124, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那可是我的女儿啊。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [124]={next_id=125, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就当是一个老父亲为了自己的女儿所做的任性之举吧。", msg_color="", msg_size=0, talker="蒂雅父亲", audio="", img="arts/ui/bg/story/storybg_9_108.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=1, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
